Origin := "http://cors.yakitest.com"
description = `CORS配置不当通常会导致的危害是用户敏感信息泄露，场景大多数是get请求方式返回的json形式的敏感信息（密钥、token，key等）`
solution = `1)不要配置“Access-Control-Allow-Origin”为通配符“*”，而且更重要的是，要严格效验来自请求数据包中的“Origin”的值。
 当收到跨域请求的时候，要检查“Origin”的值是否是一个可信的源，还要检查是否为null
2)避免使用“Access-Control-Allow-Credentials: true”
3)减少Access-Control-Allow-Methods所允许的方法`
# mirrorNewWebsitePathParams 每新出现一个网站路径且带有一些参数，参数通过常见位置和参数名去重，去重的第一个 HTTPFlow 在这里被调用
mirrorNewWebsitePathParams = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    req = poc.ReplaceHTTPPacketHeader(req,"Origin", Origin)
    resRaw, reqRaw, err = poc.HTTP(req, poc.https(isHttps))
    if err != nil{
        yakit.Warn("%v请求失败！"%url)
    }
    header, bodyRaw = str.SplitHTTPHeadersAndBodyFromPacket(resRaw)
    if Origin in header && "Access-Control-Allow-Credentials: true" in header{
        yakit.Info(sprintf("%v存在CORS配置不当",url))
        risk.NewRisk(url,
        risk.title(sprintf("%v 存在CORS配置不当", url)),
        risk.titleVerbose(sprintf("检测到CORS配置不当：%v", url)),
        risk.type("cors"),
        risk.severity("low"),
        risk.request(reqRaw),
        risk.response(resRaw),
        risk.description(description),
        risk.payload(Origin),
        risk.solution(solution)
        )
    }

}
